instance.peoplecode_text:
If %UserId = "QI8A" Or
      %UserId = "QI8A" Then

   Local string &rncntrl;
   Local ProcessRequest &procRqst;
   Local Record &recRun, &recParm;
   Local string &strBindValue;

   /* delete the old file in /tmp before copying the new file in */
   &fileTrace = GetFile("/tmp/" | XYZ_TRC_UTL_DVW.DESCR125.Value, "r", %FilePath_Absolute);
   If &fileTrace <> Null Then
      &fileTrace.Delete();
   End-If;

   /* copy the trace file to /tmp */
   &ExitCode = Exec("cp " | XYZ_TRC_UTL_DVW.DESCR254.Value | " /tmp", %Exec_Synchronous + %FilePath_Absolute);
   rem WinMessage("&ExitCode=" | &ExitCode);

   &rncntrl = "TRC_DUMP_XYZ";
   &strBindValue = XYZ_TRC_UTL_DVW.DESCR125.Value;

   &recRun = CreateRecord(Record.AEREQUESTTBL);

   /*Create run control */
   &recRun.OPRID.Value = %OperatorId;
   &recRun.RUN_CNTL_ID.Value = &rncntrl;
   &recRun.AE_APPLID.Value = "TRC_DUMP_XYZ";

   If &recRun.SelectByKey() Then
      &recRun.Update();
   Else
      &recRun.OPRID.Value = %OperatorId;
      &recRun.RUN_CNTL_ID.Value = &rncntrl;
      &recRun.AE_APPLID.Value = "TRC_DUMP_XYZ";
      &recRun.Insert();
   End-If;

   &recParm = CreateRecord(Record.AEREQUESTPARM);

   /*Create run control parameters for equity id*/
   &recParm.OPRID.Value = %OperatorId;
   &recParm.RUN_CNTL_ID.Value = &rncntrl;
   &recParm.AE_APPLID.Value = "TRC_DUMP_XYZ";
   &recParm.AE_STATE_RECNAME.Value = "XYZ_TRC_DMP_AET";
   &recParm.AE_BIND_VAR.Value = "DESCR125";

   If &recParm.SelectByKey() Then
      &recParm.AE_BIND_VALUE.Value = &strBindValue;
      &recParm.Update();
   Else
      &recParm.OPRID.Value = %OperatorId;
      &recParm.RUN_CNTL_ID.Value = &rncntrl;
      &recParm.AE_APPLID.Value = "TRC_DUMP_XYZ";
      &recParm.AE_STATE_RECNAME.Value = "XYZ_TRC_DMP_AET";
      &recParm.AE_BIND_VAR.Value = "DESCR125";
      &recParm.AE_BIND_VALUE.Value = &strBindValue;
      &recParm.Insert();
   End-If;

   &procRqst = CreateProcessRequest();
   &procRqst.ProcessType = "Application Engine";
   &procRqst.ProcessName = "TRC_DUMP_XYZ";
   &procRqst.RunControlID = &recParm.RUN_CNTL_ID.Value;
   &procRqst.RunLocation = "PSUNX"; /* server name */
   &procRqst.Schedule();

   If &procRqst.Status <> 0 Then
      MessageBox(0, "", 9999, 999, "ERROR!!!  TRC_DUMP_XYZ Failed");
      Exit (1);
   Else
      MessageBox(0, "", 9999, 999, "TRC_DUMP_XYZ has been invoked, check the process status from Process Monitor %1.", &procRqst.ProcessInstance);
   End-If;

   <*- 
   REM Delete existing  runcntlid;
   SQLExec("Delete from psprcsruncntl where oprid = :1 and runcntlid = :2", %OperatorId, &rncntrl);

   REM Insert runcntlid;
   SQLExec("Insert into psprcsruncntl (VERSION, OPRID, RUNCNTLID, RUNLOCATION, SERVERNAME, OUTDESTTYPE, OUTDESTFORMAT,  SRVRDESTFILE, SRVRDESTPRINTER, CLNTDESTFILE, CLNTDESTPRINTER, LASTUPDOPRID) VALUES (0, :1, :2, ' ', 'PSUNX', ' ', ' ', ' ', ' ', ' ', ' ', ' ')", %OperatorId, &rncntrl);

   REM Delete existing AE Request;
   &sqlStmt = CreateSQL("DELETE FROM PS_AEREQUESTTBL WHERE OPRID = :1 AND RUN_CNTL_ID = :2");
   &sqlStmt.Execute(%OperatorId, &rncntrl);
   &sqlStmt = CreateSQL("DELETE FROM PS_AEREQUESTPARM WHERE OPRID = :1 AND RUN_CNTL_ID = :2");
   &sqlStmt.Execute(%OperatorId, &rncntrl);

   REM Create SQL to insert PS_AEREQUESTTBL;
   &sqlStmt = CreateSQL("INSERT INTO PS_AEREQUESTTBL (OPRID, RUN_CNTL_ID, AE_APPLID, CURTEMPINSTANCE, PROCESS_FREQUENCY, AE_PROCESS_STATUS, PROCESS_INSTANCE, PROCESS_ORIG, MARKET) VALUES (:1, :2, 'TRC_DUMP_XYZ', 1, 'A','N',0,' ','GBL')");
   &sqlStmt.Execute(%OperatorId, &rncntrl);

   REM Create SQL to insert PS_AEREQUESTPARM;
   &sqlStmt = CreateSQL("INSERT INTO PS_AEREQUESTPARM (OPRID, RUN_CNTL_ID, AE_APPLID, AE_STATE_RECNAME, AE_BIND_VAR, AE_BIND_VALUE) VALUES (:1, :2, 'TRC_DUMP_XYZ', :3, :4, :5)");
   &sqlStmt.Execute(%OperatorId, &rncntrl, "XYZ_TRC_DMP_AET", "DESCR254", "TRC");

   REM Delete existing row from PS_TRC_DUMP_XYZ_RQST;
   &sqlStmt = CreateSQL("DELETE FROM PS_TRC_DUMP_XYZ_RQST WHERE OPRID =:1 AND RUN_CNTL_ID = :2");
   &sqlStmt.Execute(%OperatorId, &rncntrl);

   REM Create SQL to insert PS_TRC_DUMP_XYZ_RQST;
   &sqlStmt = CreateSQL("INSERT INTO PS_TRC_DUMP_XYZ_RQST(OPRID, RUN_CNTL_ID, REQUEST_ID, PROCESS_FREQUENCY, PROCESS_STATUS, PROCESS_INSTANCE, PROCESS_ORIG, DTTM_STAMP_SEC, PARALLEL_SW, PROCESSING_SEQ, INTFC_ID, TO_INTFC_ID, SYSTEM_SOURCE, BUSINESS_UNIT, AMI_RUN_BB, WA_CAP_LIM_SW, MULTI_SEL_OPTN) VALUES(:1, :2, '1', 'A', 'N', 0, 'P', %DateTimeNull, 'N', 0, :3, :4, 'TRC', ' ', 'N', 'N', 'N')");
   &sqlStmt.Execute(%OperatorId, &rncntrl);

   REM Close cursors;
   &sqlStmt.Close();

   &procRqst = CreateProcessRequest();
   &procRqst.ProcessType = "Application Engine";
   &procRqst.ProcessName = "TRC_DUMP_XYZ";
   &procRqst.RunControlID = &rncntrl;
   &procRqst.RunLocation = "PSUNX";
   &procRqst.Schedule();

   If &procRqst.Status <> 0 Then
      MessageBox(0, "", 8010, 394, "ERROR!!!  TRC_DUMP_XYZ Failed");
   Else
      MessageBox(0, "", 8010, 393, "TRC_DUMP_XYZ has been invoked, check the process status from Process Monitor.", &procRqst.ProcessInstance);
   End-If;
   *>
End-If;

If %UserId = "QI8A" Or
      %UserId = "QI8A" Then
   XYZ_TRC_UTL_DVW.VIEW_PB.Visible = True;
   XYZ_TRC_UTL_DVW.VIEW_PB.Visible = True;
Else
   XYZ_TRC_UTL_DVW.VIEW_PB.Visible = False;
End-If;

import XYZ_DELETE_TRACE:*;

Component XYZ_DELETE_TRACE:DeleteTraceFile &DelTrace;

&DelTrace = create XYZ_DELETE_TRACE:DeleteTraceFile();

class DeleteTraceFile
   method DeleteTraceFile();
   method HandleEvent(&intRow As integer, &inField As Field, &inEventName As string);
private
   method initialize();
   method Refresh();
   method DeleteAll();
   method Delete(&intRow As integer);
   method InitEvent(&intRow As integer, &inField As Field);
   method ChangeAppServer();

   instance Rowset &ROWSET_LEVEL0, &ROWSET_LEVEL1;
   instance string &TRACE_DIR, &TRACE_DIR_DB, &HTTP_URL, &HTTP_URL_DB, &INSTANCE, &DIR_FILES;
   instance array of string &FNAMES;
end-class;


method DeleteTraceFile
   %This.initialize();
end-method;

method initialize

   &TRACE_DIR = GetEnv("XYZ_TRACE") | "/";
   %This.Refresh();

end-method;

method Refresh

   Local integer &rownum;
   Local string &Filename, &ShortFilename;
   Local string &strURI;
   Local integer &find;

   &ROWSET_LEVEL0 = GetLevel0();
   &ROWSET_LEVEL1 = &ROWSET_LEVEL0.GetRow(1).GetRowset(Scroll.XYZ_TRC_UTL_DVW);
   &ROWSET_LEVEL1.Flush();

   &TRACE_DIR_DB = &TRACE_DIR | XYZ_TRC_UTL_WRK.ENV_NAME_XYZ.LongTranslateValue | "/";
   &strURI = %Session.GetLocalNode().PortalURI;
   &find = Find(":", &strURI, 7);
   XYZ_TRC_UTL_WRK.URL_1.Value = Substring(&strURI, 1, &find) | "30091/TRACE/FS" | XYZ_TRC_UTL_WRK.ENV_NAME_XYZ.Value | "/";;

   /* Populate the grid with login ID trace */
   REM &DIR_FILES = &TRACE_DIR_DB | "*.tracesql";
   &DIR_FILES = &TRACE_DIR_DB | %UserId | "*.tracesql";
   &FNAMES = FindFiles(&DIR_FILES, %FilePath_Absolute);

   &rownum = 1;

   While &FNAMES.Len > 0
      &Filename = &FNAMES.Shift();
      If Substring(&Filename, Len(&TRACE_DIR_DB) + 1, 5) <> "PSAPP" Then
         /* List the files */
         If &rownum = 1 Then /* this just prevents a blank line */
            &rownum = 0;
         Else
            &ROWSET_LEVEL1.InsertRow(0);
         End-If;
         &ROWSET_LEVEL1.GetRow(1).GetRecord(Record.XYZ_TRC_UTL_DVW).DESCR254.Value = &Filename;
         &ShortFilename = Substring(&Filename, Len(&TRACE_DIR_DB) + 1, Len(&Filename) - Len(&TRACE_DIR_DB));
         &ROWSET_LEVEL1.GetRow(1).GetRecord(Record.XYZ_TRC_UTL_DVW).DESCR125.Value = &ShortFilename;
      End-If;
   End-While;

   /* Populate the grid with O Ids */
   REM &DIR_FILES = &TRACE_DIR_DB | "*.tracesql";
   &DIR_FILES = &TRACE_DIR_DB | "O*.tracesql";
   If %UserId = "QI8A" Or
         %UserId = "QI8A" Then
      &DIR_FILES = &TRACE_DIR_DB | "*.tracesql";
   End-If;

   &FNAMES = FindFiles(&DIR_FILES, %FilePath_Absolute);

   While &FNAMES.Len > 0
      &Filename = &FNAMES.Shift();

      If Substring(&Filename, Len(&TRACE_DIR_DB) + 1, 5) <> "PSAPP" Or
            Substring(&Filename, Len(&TRACE_DIR_DB) + 1, 14) = "PSAPP_PSSUBHND" Or
            Find("JavaClient", &Filename) > 0 Then
         /* List the files */
         If &rownum = 1 Then /* this just prevents a blank line */
            &rownum = 0;
         Else
            &ROWSET_LEVEL1.InsertRow(0);
         End-If;
         &ROWSET_LEVEL1.GetRow(1).GetRecord(Record.XYZ_TRC_UTL_DVW).DESCR254.Value = &Filename;
         &ROWSET_LEVEL1.GetRow(1).GetRecord(Record.XYZ_TRC_UTL_DVW).DESCR125.Value = Substring(&Filename, Len(&TRACE_DIR_DB) + 1, Len(&Filename) - Len(&TRACE_DIR_DB));
      End-If;

   End-While;


   /* Populate the grid with O Ids */
   REM &DIR_FILES = &TRACE_DIR_DB | "*.tracesql";
   &DIR_FILES = &TRACE_DIR_DB | "o*.tracesql";

   &FNAMES = FindFiles(&DIR_FILES, %FilePath_Absolute);

   While &FNAMES.Len > 0
      &Filename = &FNAMES.Shift();
      If Substring(&Filename, Len(&TRACE_DIR_DB) + 1, 5) <> "PSAPP" Then
         /* List the files */
         If &rownum = 1 Then /* this just prevents a blank line */
            &rownum = 0;
         Else
            &ROWSET_LEVEL1.InsertRow(0);
         End-If;
         &ROWSET_LEVEL1.GetRow(1).GetRecord(Record.XYZ_TRC_UTL_DVW).DESCR254.Value = &Filename;
         &ROWSET_LEVEL1.GetRow(1).GetRecord(Record.XYZ_TRC_UTL_DVW).DESCR125.Value = Substring(&Filename, Len(&TRACE_DIR_DB) + 1, Len(&Filename) - Len(&TRACE_DIR_DB));
      End-If;
   End-While;

   &ROWSET_LEVEL1.Sort(XYZ_TRC_UTL_DVW.DESCR125, "A");

end-method;

method Delete
   /+ &intRow as Integer +/

   Local File &MyFile;
   Local string &str;

   /* Delete only trace files */
   &ROWSET_LEVEL0 = GetLevel0();
   &ROWSET_LEVEL1 = &ROWSET_LEVEL0.GetRow(1).GetRowset(Scroll.XYZ_TRC_UTL_DVW);

   If All(&ROWSET_LEVEL1(&intRow).XYZ_TRC_UTL_DVW.DESCR254.Value) Then
      &MyFile = GetFile(XYZ_TRC_UTL_DVW.DESCR254.Value, "R", %FilePath_Absolute);
      &MyFile.Delete();
      &str = String(%Datetime);
      &ROWSET_LEVEL1(&intRow).XYZ_TRC_UTL_DVW.DESCR15.Value = Substring(&str, 6, Len(&str) - 7);
   Else
      WinMessage("No file to delete.");
   End-If;

end-method;

method DeleteAll

   Local File &MyFile;
   Local string &Filename;
   Local integer &i;

   /* Delete only trace files */
   &ROWSET_LEVEL0 = GetLevel0();
   &ROWSET_LEVEL1 = &ROWSET_LEVEL0.GetRow(1).GetRowset(Scroll.XYZ_TRC_UTL_DVW);

   For &i = 1 To &ROWSET_LEVEL1.ActiveRowCount
      &Filename = &ROWSET_LEVEL1(&i).XYZ_TRC_UTL_DVW.DESCR254.Value;
      rem WinMessage(&Filename);
      If All(&Filename) And
            Substring(&Filename, Len(&TRACE_DIR_DB) + 1, 5) <> "PSAPP" Then
         &MyFile = GetFile(&Filename, "R", %FilePath_Absolute);
         &MyFile.Delete();
      End-If;
   End-For;
   %This.Refresh();

end-method;

method ChangeAppServer
   /* refresh the grid */
   %This.Refresh();
end-method;

method HandleEvent
   /+ &intRow as Integer, +/
   /+ &inField as Field, +/
   /+ &inEventName as String +/

   Local integer &i;

   &i = &intRow;
   %This.InitEvent(&i, &inField As Field);

   Evaluate &inEventName
   When = "FieldChange"

      Evaluate &inField.Name
      When = Field.REFRESH_BTN
         %This.Refresh();
         Break;

      When = Field.DELETE_PB
         %This.Delete(&intRow);
         Break;

      When = Field.DELETE_ALL_PB
         %This.DeleteAll();
         Break;

      When = Field.ENV_NAME_XYZ
         %This.ChangeAppServer();
         Break;

      When-Other
      End-Evaluate;

      Break;
   When-Other
   End-Evaluate;

end-method;

method InitEvent
   /+ &intRow as Integer, +/
   /+ &inField as Field +/

   /* Add code here if there are some initial steps to be done before the event */
end-method;
